def findMedianSortedArrays(nums1, nums2):
    # 对较短数组做二分切分，使左半元素数 = (m+n+1)//2 且左半最大值 <= 右半最小值
    A, B = nums1, nums2
    if len(A) > len(B):
        A, B = B, A
    m, n = len(A), len(B)
    lo, hi = 0, m
    total_left = (m + n + 1) // 2
    while lo <= hi:
        i = (lo + hi) // 2
        j = total_left - i
        if i < m and A[i] < B[j - 1]:
            lo = i + 1
        elif i > 0 and A[i - 1] > B[j]:
            hi = i - 1
        else:
            if i == 0:
                max_left = B[j - 1]
            elif j == 0:
                max_left = A[i - 1]
            else:
                max_left = max(A[i - 1], B[j - 1])
            if (m + n) % 2 == 1:
                return float(max_left)
            if i == m:
                min_right = B[j]
            elif j == n:
                min_right = A[i]
            else:
                min_right = min(A[i], B[j])
            return (max_left + min_right) / 2.0
    return 0.0

